"""3.4 - Konfidens dari logit dan gerbang sigmoid g(c)."""
import numpy as np
from scipy.special import softmax


def conf_softmax(z):
    """Pers. (3-2): c = max softmax(z). Untuk C kelas, c berada di [1/C, 1]."""
    return softmax(z, axis=1).max(axis=1)


def gate(c, tau=0.5, k=10.0):
    """Pers. (3-4): g(c) = 1 / (1 + exp(-k (c - tau)))."""
    return 1.0 / (1.0 + np.exp(-k * (c - tau)))

"""3.8: uji berpasangan dan interval kepercayaan untuk selisih RMSE."""
import numpy as np
from scipy import stats


def rmse_gain_pct(se_base, se_new):
    """Penurunan RMSE relatif (%) ; se_* = galat kuadrat per sampel uji."""
    return 100 * (1 - np.sqrt(se_new.mean()) / np.sqrt(se_base.mean()))


def paired_bootstrap_ci(se_base, se_new, n_boot=2000, alpha=0.05, seed=0):
    """CI persentil untuk penurunan RMSE; sampel uji diacak ULANG BERPASANGAN."""
    rng = np.random.default_rng(seed)
    n = len(se_base)
    gains = np.empty(n_boot)
    for b in range(n_boot):
        idx = rng.integers(0, n, n)
        gains[b] = rmse_gain_pct(se_base[idx], se_new[idx])
    return np.percentile(gains, [100 * alpha / 2, 100 * (1 - alpha / 2)])


def per_seed_summary(se_base_by_seed, se_new_by_seed):
    """Wilcoxon per seed (pada galat kuadrat per sampel) + p gabungan Fisher.
    Semua seed memakai set uji yang sama, jadi p gabungan hanyalah ringkasan."""
    p = [stats.wilcoxon(b, n).pvalue for b, n in zip(se_base_by_seed, se_new_by_seed)]
    fisher = stats.combine_pvalues(p, method="fisher").pvalue
    return {"p_per_seed": p, "n_sig": int(sum(x < 0.05 for x in p)), "p_fisher": fisher}

"""O3: estimasi mood sesi (Pers. 5-11, 5-12) dengan bobot keyakinan."""
import numpy as np

def ewma_step(m_prev, v, alpha, kappa=1.0):
    """Satu langkah EWMA; kappa kecil -> item meragukan menggeser mood sedikit."""
    if m_prev is None:
        return np.asarray(v, float)
    a = alpha * kappa
    return a * np.asarray(v, float) + (1 - a) * m_prev

def update_mood(state, v, kappa=1.0, a_main=0.5, a_short=0.6, a_long=0.2, theta=0.35):
    """state: dict berisi 'm', 'short', 'long' (None di awal sesi).
    Mengembalikan state baru, mood teramati, dan tanda peralihan."""
    s = {k: ewma_step(state.get(k), v, a, kappa)
         for k, a in (("m", a_main), ("short", a_short), ("long", a_long))}
    shift = np.linalg.norm(s["short"] - s["long"]) > theta
    mood = s["short"] if shift else s["m"]        # ikuti EWMA pendek saat beralih
    return s, mood, bool(shift)

def target_mood(m, m_goal=None, gamma=0.0):
    """Pers. (5-13): gamma = 0 -> selaras; gamma > 0 -> regulasi ke m_goal."""
    if m_goal is None or gamma == 0:
        return m
    return m + gamma * (np.asarray(m_goal, float) - m)

"""Metrik prediksi skor dan ketepatan daftar (Pers. 6-1 s.d. 6-5)."""
import numpy as np


def mae_rmse(r, r_hat):
    e = np.asarray(r, float) - np.asarray(r_hat, float)
    return np.abs(e).mean(), np.sqrt((e ** 2).mean())


def _hits(ranked, rel, K):
    return np.array([1.0 if i in rel else 0.0 for i in ranked[:K]])


def hit_rate(ranked, rel, K):
    return float(_hits(ranked, rel, K).sum() > 0)


def precision(ranked, rel, K):
    return _hits(ranked, rel, K).sum() / K


def recall(ranked, rel, K):
    return _hits(ranked, rel, K).sum() / max(len(rel), 1)


def f1(ranked, rel, K):
    p, r = precision(ranked, rel, K), recall(ranked, rel, K)
    return 0.0 if p + r == 0 else 2 * p * r / (p + r)


def reciprocal_rank(ranked, rel, K):
    h = _hits(ranked, rel, K)
    return 0.0 if h.sum() == 0 else 1.0 / (np.argmax(h) + 1)


def average_precision(ranked, rel, K):
    h = _hits(ranked, rel, K)
    prec_at_k = np.cumsum(h) / np.arange(1, len(h) + 1)
    return (h * prec_at_k).sum() / max(min(len(rel), K), 1)


def ndcg(ranked, rel, K):
    """rel: {item: tingkat relevansi}. Perolehan 2^g - 1 (biner: g = 1)."""
    disc = 1.0 / np.log2(np.arange(2, K + 2))
    gains = np.array([2.0 ** rel.get(i, 0) - 1 if i in rel else 0.0 for i in ranked[:K]])
    ideal = np.sort([2.0 ** g - 1 for g in rel.values()])[::-1][:K]
    idcg = (ideal * disc[:len(ideal)]).sum()
    return 0.0 if idcg == 0 else (gains * disc[:len(gains)]).sum() / idcg

"""Metrik di luar akurasi dan keselarasan emosi (Pers. 6-6 s.d. 6-12)."""
from itertools import combinations
import numpy as np

DIAG = 2 * np.sqrt(2)  # jarak terjauh dua titik di [-1, 1]^2


def coverage(lists, n_items):
    return len({i for L in lists for i in L}) / n_items


def gini(exposure):
    x = np.sort(np.asarray(exposure, float))
    n = len(x)
    return ((2 * np.arange(1, n + 1) - n - 1) * x).sum() / (n * x.sum())


def novelty(ranked, pop, n_users):
    return float(np.mean([-np.log2(pop[i] / n_users) for i in ranked]))


def ild(ranked, va):
    V = np.array([va[i] for i in ranked])
    d = [np.linalg.norm(V[a] - V[b]) / DIAG for a, b in combinations(range(len(V)), 2)]
    return float(np.mean(d))


def align(v, m):
    return 1.0 - np.linalg.norm(np.asarray(v) - np.asarray(m)) / DIAG


def quadrant(v):
    if v[0] >= 0:
        return 0 if v[1] >= 0 else 3
    return 1 if v[1] >= 0 else 2


def eas(ranked, va, m, weighted=False):
    a = np.array([align(va[i], m) for i in ranked])
    w = 1.0 / np.log2(np.arange(2, len(a) + 2)) if weighted else np.ones(len(a))
    return float((w * a).sum() / w.sum())


def qhr(ranked, va, m):
    return float(np.mean([quadrant(va[i]) == quadrant(m) for i in ranked]))


def affective_kl(ranked, va, p_hist, eps=0.01):
    q = np.bincount([quadrant(va[i]) for i in ranked], minlength=4) / len(ranked)
    p = np.asarray(p_hist, float)
    q_s = (1 - eps) * q + eps * p
    nz = p > 0
    return float((p[nz] * np.log2(p[nz] / q_s[nz])).sum())

"""Uji berpasangan, bootstrap, koreksi Holm, dan besar efek (Pers. 6-13, 6-14)."""
import numpy as np
from scipy import stats


def paired_tests(m_a, m_b):
    d = np.asarray(m_b, float) - np.asarray(m_a, float)
    nz = d[d != 0]  # Wilcoxon mengabaikan selisih nol
    p_w = stats.wilcoxon(nz).pvalue if len(nz) > 0 else 1.0
    p_t = stats.ttest_rel(m_b, m_a).pvalue
    return {"mean_diff": d.mean(), "p_wilcoxon": p_w, "p_ttest": p_t,
            "d_z": d.mean() / d.std(ddof=1),
            "n_better": int((d > 0).sum()), "n_worse": int((d < 0).sum())}


def bootstrap_ci(m_a, m_b, n_boot=2000, alpha=0.05, seed=0):
    d = np.asarray(m_b, float) - np.asarray(m_a, float)
    rng = np.random.default_rng(seed)
    idx = rng.integers(0, len(d), size=(n_boot, len(d)))
    means = d[idx].mean(axis=1)
    return np.percentile(means, [100 * alpha / 2, 100 * (1 - alpha / 2)])


def holm(pvalues, alpha=0.05):
    """True bila hipotesis nol ditolak. Urutan hasil sama dengan urutan masukan."""
    p = np.asarray(pvalues)
    m = len(p)
    reject = np.zeros(m, bool)
    for j, idx in enumerate(np.argsort(p)):
        if p[idx] <= alpha / (m - j):
            reject[idx] = True
        else:
            break
    return reject.tolist()
